    const attrs = {};
    const remaining = raw.replace(/([\w-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g, (_, name, a, b) => {
      u.check(u.id(name) && !u.own(attrs, name), '重复或非法标签属性：' + name);
